import { Component, computed, inject, signal } from '@angular/core';
import { CommonModule, Location } from '@angular/common';
import { ActivatedRoute, Router } from '@angular/router';
import { forkJoin } from 'rxjs';
import { SolicitudService } from '../../../shared/services/solicitud.service';
import { TramiteService } from '../../../shared/services/tramite.service';
import { Solicitud, SolicitudTramite } from '../../../shared/models/solicitud.model';
import { DocumentUploaderComponent } from '../../../shared/components/document-uploader/document-uploader';
import { extractErrorMessage } from '../../../shared/utils/error-utils';

@Component({
  selector: 'app-seguimiento-tramites',
  standalone: true,
  imports: [CommonModule, DocumentUploaderComponent],
  templateUrl: './seguimiento-tramites.component.html',
})
export class SeguimientoTramitesComponent {
  private readonly route = inject(ActivatedRoute);
  private readonly solicitudService = inject(SolicitudService);
  private readonly tramiteService = inject(TramiteService);
  private readonly router = inject(Router);
  private readonly location = inject(Location);

  readonly folio = signal<string>('');
  readonly solicitud = signal<Solicitud | null>(null);
  readonly tramites = signal<SolicitudTramite[]>([]);
  readonly loading = signal(false);
  readonly error = signal<string | null>(null);
  readonly deletingTramiteId = signal<number | null>(null);
  readonly tramiteToDelete = signal<number | null>(null);

  isDeleting(tramiteId: number): boolean {
    return this.deletingTramiteId() === tramiteId;
  }

  onDocumentIdChange(tramiteId: number, documentId: number | null): void {
    if (documentId) {
      this.tramiteService.vincularDocumentoTramite(this.folio(), tramiteId, documentId).subscribe({
        next: () => {
          this.cargar(true);
        },
        error: (err) => {
          this.error.set(extractErrorMessage(err));
        },
      });
    } else {
      this.deletingTramiteId.set(tramiteId);
      this.tramiteService.desvincularDocumentoTramite(this.folio(), tramiteId).subscribe({
        next: () => {
          this.deletingTramiteId.set(null);
          this.cargar(true);
        },
        error: (err) => {
          this.deletingTramiteId.set(null);
          this.error.set(extractErrorMessage(err));
        },
      });
    }
  }

  readonly progreso = computed(() => {
    const ts = this.tramites();
    const total = ts.length;
    if (total === 0) {
      return { total: 0, completados: 0, subidos: 0, pctCompletados: 0, pctSubidos: 0 };
    }
    const completados = ts.filter(t => t.estado === 'completado').length;
    const subidos = ts.filter(t => t.estado === 'documento_subido').length;
    const pctCompletados = Math.round((completados / total) * 100);
    const pctSubidos = Math.round((subidos / total) * 100);
    return {
      total,
      completados,
      subidos,
      pctCompletados,
      pctSubidos,
    };
  });

  constructor() {
    const folio = this.route.snapshot.paramMap.get('folio') ?? '';
    this.folio.set(folio);
    this.cargar();
  }

  goBack(): void {
    if (window.history.length > 1) {
      this.location.back();
    } else {
      this.router.navigate(['/inversores/autorizaciones']);
    }
  }

  cargar(silent = false): void {
    if (!silent) {
      this.loading.set(true);
    }
    forkJoin({
      solicitud: this.solicitudService.getByFolio(this.folio()),
      tramites: this.tramiteService.getTramitesAsignados(this.folio()),
    }).subscribe({
      next: ({ solicitud, tramites }) => {
        tramites.forEach((t) => {
          if (t.estado === 'rechazado') {
            localStorage.removeItem('doc_upload_file-' + t.id);
          }
        });
        this.solicitud.set(solicitud);
        this.tramites.set(tramites);
        this.loading.set(false);
      },
      error: (err) => {
        this.loading.set(false);
        this.error.set(extractErrorMessage(err));
      },
    });
  }

  estadoBadgeClass(estado: string): string {
    switch (estado) {
      case 'pendiente': return 'bg-secondary';
      case 'documento_subido': return 'bg-warning text-dark';
      case 'completado': return 'bg-success';
      case 'rechazado': return 'bg-danger';
      default: return 'bg-secondary';
    }
  }

  semaforoTramite(t: SolicitudTramite): { status: string; label: string; colorClass: string } {
    if (t.estado === 'completado') {
      return { status: 'completed', label: 'Completado', colorClass: 'bg-success' };
    }

    const dias = t.vigenciaDias;
    if (!dias) {
      return { status: 'none', label: 'Sin vigencia', colorClass: 'bg-secondary' };
    }

    const asignacion = new Date(t.fecha_asignacion.replace(' ', 'T') + 'Z');
    const ahora = new Date();
    const diffMs = ahora.getTime() - asignacion.getTime();
    const diasTranscurridos = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    const diasRestantes = dias - diasTranscurridos;

    if (diasRestantes >= 21) {
      return { status: 'green', label: `${diasRestantes} días restantes`, colorClass: 'bg-success' };
    }
    if (diasRestantes >= 11) {
      return { status: 'yellow', label: `${diasRestantes} días restantes`, colorClass: 'bg-warning' };
    }
    if (diasRestantes >= 0) {
      return { status: 'red', label: `${diasRestantes} días restantes`, colorClass: 'bg-danger' };
    }
    return { status: 'overdue', label: `Vencido (hace ${Math.abs(diasRestantes)} días)`, colorClass: 'bg-danger' };
  }
}
